.parent-sign-box{margin:6px 0 0;padding:6px;border:1px solid #d5e0eb;background:#f8fafc;border-radius:5px}.parent-sign-box h3{margin:0 0 3px;color:#173f6d;font-size:7px}.parent-sign-box p{margin:2px 0;color:#66758a;font-size:6.4px}.parent-sign-box input{max-width:100%;font-size:7px}.parent-sign-box button{margin-top:3px;padding:5px 8px;border:0;border-radius:4px;background:#173f6d;color:#fff;font-weight:700;font-size:7px;cursor:pointer}
.footer{margin-top:3px;padding-top:3px;border-top:1px solid #dbe2e9;text-align:center;color:#8793a2;font-size:5.3px}
