@media print{html,body{background:#fff}.sheet{max-width:none;width:100%;margin:0;border:0;box-shadow:none;padding:0}.actions,.parent-sign-box,.success,.errors{display:none}.header,.identity,.summary,.two-col,.signatures,.table,.note{break-inside:avoid;page-break-inside:avoid}.table tr{break-inside:avoid;page-break-inside:avoid}.footer{margin-top:2px}}
